import { useMemo } from 'react';

import { LineBarChartsSectionData } from 'components/Chart/lineBarChart';
import { useBffData, usePageFilterApplied } from 'hooks';
import {
  PERFORMANCE_TOOL_MARKET_SHARE_OFFICIAL_LINE_BAR_CHARTS_BFF_ID,
  PERFORMANCE_TOOL_PAGE_NAME,
} from 'pages/pillars/ValueCreation/PerformanceTool/constants';
import { deriveTimePeriodHighlightedIndexes } from 'pages/pillars/ValueCreation/PerformanceTool/utils';
import {
  getMarketShareOfficialSubFilters,
  getPerformanceToolSubFilters,
} from 'pages/pillars/ValueCreation/PerformanceTool/utils/getPerformanceToolSubFilters';

export const useLineBarChartData = (
  requestPeriodType: string,
  lineChartPeriodType: string,
  lineChartDtEnd: string,
  lineChartCutoffDate: string,
) => {
  const { applied } = usePageFilterApplied(PERFORMANCE_TOOL_PAGE_NAME);

  const lineBarChartBffData = useBffData({
    id: PERFORMANCE_TOOL_MARKET_SHARE_OFFICIAL_LINE_BAR_CHARTS_BFF_ID,
    kpiGroup: 'market_share_official_total',
    subFilters: {
      ...getPerformanceToolSubFilters(applied),
      ...getMarketShareOfficialSubFilters(applied),
      period_type: requestPeriodType,
    },
    skipMainFilters: false,
  });

  const isEmpty = useMemo(() => {
    return lineBarChartBffData?.data?.empty;
  }, [lineBarChartBffData.data]);
  const isLoading = useMemo(() => {
    return lineBarChartBffData.loading;
  }, [lineBarChartBffData.loading]);
  const isError = useMemo(() => {
    return lineBarChartBffData.error;
  }, [lineBarChartBffData.error]);

  const data = lineBarChartBffData?.data?.[
    'line-bar-charts'
  ] as unknown as LineBarChartsSectionData;

  const lineBarChartsData = useMemo(() => {
    const { labels, datasets } = data?.lineChart ?? {
      labels: [],
      datasets: [],
    };

    const highlightedIndexes = deriveTimePeriodHighlightedIndexes({
      periodType: lineChartPeriodType,
      dtEnd: lineChartDtEnd,
      cutoffDate: lineChartCutoffDate,
      labels,
      datasets,
    });

    return {
      ...data,
      lineChart: {
        ...data?.lineChart,
        highlightedIndexes,
      },
    };
  }, [lineChartDtEnd, lineChartPeriodType, lineChartCutoffDate, data]);

  return {
    empty: isEmpty,
    loading: isLoading,
    error: isError,
    data: lineBarChartsData,
  };
};
